use super::*;
use semio_framework_trace::observe_heap_allocations_on_this_thread;
use semio_framework_value::retirement::{OwnedValueRetirementFactory,SharedValueRetirementFactory};

fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:32768,maximum_release_bytes:32768,maximum_depth:64}}
fn original()->ArtifactStoreOneItemPrepared<String,String>{
    let actor=semio_framework_value::SharedUtf8::admit("actor".to_string(),grant()).unwrap_or_else(|_|panic!("funded original actor")).0;
    let authority=Arc::new(ArtifactStoreOneItemLiveAuthority::mint(semio_framework_job::OperationId(11),semio_framework_job::Generation(7),[9;32],3,4,HybridLogicalTimestamp{actor:1,physical_ms:42,logical:2},actor,None,None,Some("edit".to_string())));
    let edit=authority.next_edit("forward".to_string(),vec!["inverse".to_string()]);let mut prepared=authority.prepare_one_item(edit,Arc::new("post".to_string())).unwrap();prepared.record_foreign_step_presence(true);
    let mut messages=crate::os_spr::command::MutationMessagePublication::new(vec![crate::os_spr::MutationMessage::warning("NOTICE","original warning")]);while !messages.ready(){messages.advance(grant()).unwrap();}prepared.record_outcome_messages(messages);prepared
}
fn pointers(prepared:&ArtifactStoreOneItemPrepared<String,String>)->[usize;8]{[prepared.edit()as*const Edit<String>as usize,Arc::as_ptr(prepared.post_snapshot())as usize,Arc::as_ptr(prepared.authority())as usize,prepared.local_actor().unwrap().chunks().next().unwrap().as_ptr()as usize,prepared.applied_edit_id().chunks().next().unwrap().as_ptr()as usize,prepared.tail_edit_id().chunks().next().unwrap().as_ptr()as usize,prepared.outcome_messages()[0].message.as_ptr()as usize,prepared.edit().forwards[0].as_ptr()as usize]}
fn retire(prepared:ArtifactStoreOneItemPrepared<String,String>){let mutations:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(OwnedValueRetirementFactory::<String>::default());let snapshots:Arc<dyn SnapshotRetirementFactory<String>>=Arc::new(SharedValueRetirementFactory::<String>::default());let(owner,_)=prepared.admit_retirement(mutations,snapshots,grant()).unwrap_or_else(|_|panic!("funded original candidate retirement"));let mut owner=Some(owner);for turn in 0..100000{if owner.is_none(){return;}let demand=artifact_retirement_box_demands(owner.as_ref().unwrap(),0).unwrap();let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};let(step,heap)=observe_heap_allocations_on_this_thread(||artifact_retirement_box_close_step(&mut owner,exact).unwrap());assert!(step.progress().fits(exact));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(turn<99999);}}

#[test]
fn prepared_binding_refusal_returns_every_original_piece_and_new_identity_owner(){
    let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();assert_eq!(law["originalPieces"].as_array().unwrap().len(),8);
    let prepared=original();let expected=pointers(&prepared);let authority=Arc::clone(prepared.authority());let(result,heap)=observe_heap_allocations_on_this_thread(||ArtifactStorePreparedBinding::admit(prepared,RetainedCloneGrant::default()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let prepared=match result{Err((_,prepared))=>prepared,Ok(_)=>panic!("unfunded binding birth")};assert_eq!(pointers(&prepared),expected);let((mut binding,birth),heap)=observe_heap_allocations_on_this_thread(||ArtifactStorePreparedBinding::admit(prepared,grant()).unwrap_or_else(|_|panic!("funded original binding")));assert!(birth.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
    let group="0".repeat(64);let pointer=group.as_ptr();let(result,heap)=observe_heap_allocations_on_this_thread(||binding.stage_group(group,RetainedCloneGrant::default()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(_,group)=result.unwrap_err();assert_eq!(group.as_ptr(),pointer);
    let(receipt,heap)=observe_heap_allocations_on_this_thread(||binding.stage_group(group,grant()).unwrap());assert!(receipt.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
    let(result,heap)=observe_heap_allocations_on_this_thread(||binding.finish_rebind(Arc::clone(&authority),[0;32],grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(_,returned)=match result{Err(refusal)=>refusal,Ok(_)=>panic!("original authority refuses staged group")};assert!(Arc::ptr_eq(&returned,&authority));drop(returned);
    assert!(binding.rollback_group(RetainedCloneGrant::default()).is_none());let((group,receipt),heap)=observe_heap_allocations_on_this_thread(||binding.rollback_group(grant()).unwrap());assert!(receipt.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(group.as_ref().unwrap().as_ptr(),pointer);assert!(binding.original().edit().mutation_meta[0].group_id.is_none());
    assert!(binding.take_original(RetainedCloneGrant::default()).is_none());let((prepared,receipt),heap)=observe_heap_allocations_on_this_thread(||binding.take_original(grant()).unwrap());assert!(receipt.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let actual=pointers(&prepared);assert_eq!(actual,expected);assert_eq!(prepared.foreign_step_presence(),Some(true));authority.validate_prepared(&prepared).unwrap();assert!(binding.terminal_is_empty());let(_,heap)=observe_heap_allocations_on_this_thread(||drop(binding));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));drop(group);drop(authority);retire(prepared);
    println!("[DEBUG] Prepared binding failed authority returns original edit/post/issuer/diagnostics/mutations and paged identities, exact new group string, independent denied grants and terminal0heap");
}

#[test]
fn prepared_binding_success_preserves_original_metadata_messages_and_paged_identity_backings(){
    let prepared=original();let expected=pointers(&prepared);let original_authority=Arc::clone(prepared.authority());let(mut binding,_)=ArtifactStorePreparedBinding::admit(prepared,grant()).unwrap_or_else(|_|panic!("funded original binding"));let group="a".repeat(64);let authority=Arc::new(original_authority.rebind_group(group.clone()));binding.stage_group(group,grant()).unwrap();let digest=authority.prepared_edit_digest(binding.edit()).unwrap();let((prepared,previous,receipt),heap)=observe_heap_allocations_on_this_thread(||binding.finish_rebind(Arc::clone(&authority),digest,grant()).unwrap_or_else(|_|panic!("validated group authority")));assert!(receipt.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let actual=pointers(&prepared);for index in [0,1,3,4,5,6,7]{assert_eq!(actual[index],expected[index]);}assert_eq!(Arc::as_ptr(&previous)as usize,expected[2]);assert_eq!(prepared.foreign_step_presence(),Some(true));authority.validate_prepared(&prepared).unwrap();assert!(binding.terminal_is_empty());let(_,heap)=observe_heap_allocations_on_this_thread(||drop(binding));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));drop(previous);drop(original_authority);drop(authority);retire(prepared);println!("[DEBUG] Prepared binding success preserves exact edit/post/paged identity/diagnostic/mutation backings and foreign-step metadata; previous issuer returned for explicit custody");
}

#[test]
fn prepared_binding_inspection_restores_all_original_pieces_on_every_planning_refusal(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let mut prepared=original();let expected=pointers(&prepared);for phase in law["refusalPhases"].as_array().unwrap(){let group="b".repeat(64);let pointer=group.as_ptr();let(result,heap)=observe_heap_allocations_on_this_thread(||ArtifactStorePreparedBinding::inspect_group(&mut prepared,group,RetainedCloneGrant::default(),|_|Ok::<(),&str>(())));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let group=match result{Err((_,group))=>group,Ok(_)=>panic!("denied field inspection")};assert_eq!(group.as_ptr(),pointer);assert_eq!(pointers(&prepared),expected);let phase=phase.as_str().unwrap();let((result,group,receipt),heap)=observe_heap_allocations_on_this_thread(||ArtifactStorePreparedBinding::inspect_group(&mut prepared,group,grant(),|staged|{assert_eq!(staged.edit().mutation_meta[0].group_id.as_deref(),Some("bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"));Err::<(),_>(phase)}).unwrap());assert_eq!(result,Err(phase));assert_eq!(group.as_ptr(),pointer);assert!(receipt.fits(grant()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(pointers(&prepared),expected);assert!(prepared.edit().mutation_meta[0].group_id.is_none());prepared.authority().validate_prepared(&prepared).unwrap();drop(group);}assert_eq!(prepared.foreign_step_presence(),Some(true));retire(prepared);println!("[DEBUG] Prepared field inspection seven neutral refusal phases return original sealed candidate and exact identity owner under independent denied/admitted grants");
}
